    task tb_check;
        begin
            if ((((count ^ e_count) & m_count) !== 0) ||
                (((err ^ e_err) & m_err) !== 0)) begin
                if (tb_errors == 0)
                    $sformat(tb_detail, "vector %0d (t=%t): t=%h -> expected count=%h err=%h, got count=%h err=%h",
                             tb_vec, $time, t, e_count, e_err, count, err);
                tb_errors = tb_errors + 1;
            end
        end
    endtask

    initial begin
        $timeformat(-9, 0, " ns", 0);
        if ($test$plusargs("vcd")) begin
            $dumpfile("wave.vcd");
            $dumpvars(1, dut);
        end
        tb_fd = $fopen("vectors.txt", "r");
        if (tb_fd == 0) begin
            $display("FAIL: testbench could not open its vector file");
            $display("TB_DONE");
