        while ($fscanf(tb_fd, "%d %h %h %h %h %h\n", tb_grp, t, e_count, m_count, e_err, m_err) == 6) begin
            if (tb_grp != tb_cur) begin
                if (tb_cur >= 0) tb_end_group;
                tb_cur = tb_grp; tb_errors = 0; tb_detail = "";
            end
            #5;
            tb_check;
            #5;
            tb_vec = tb_vec + 1;
        end
        if (tb_cur >= 0) tb_end_group;
        if (tb_vec != 2136)
            $display("FAIL: testbench read %0d of 2136 vectors", tb_vec);
        $display("TB_DONE");
        $finish;
    end

    initial begin
